mapper.select:
SELECT p.id, p.tenant_id, p.title, p.type, p.status, p.description, p.linked_kb_id, p.metadata, p.created_by, p.created_at, p.updated_at, COALESCE(c.chapter_count, 0) AS chapter_count, COALESCE(d.script_draft_count, 0) AS script_draft_count FROM story_project p LEFT JOIN ( SELECT project_id, COUNT(*) AS chapter_count FROM story_chapter GROUP BY project_id ) c ON c.project_id = p.id LEFT JOIN ( SELECT project_id, COUNT(*) AS script_draft_count FROM story_script_draft GROUP BY project_id ) d ON d.project_id = p.id WHERE p.tenant_id = #{tenantId}
AND p.type = #{type}
ORDER BY p.updated_at DESC

mapper.update:
UPDATE story_project
SET status = #{status}, updated_at = NOW()
WHERE id = #{id}
